statement:
This is an interactive problem. Houses stand in a circle along a street, and each house's door is either open or closed at the start. You are standing in front of one of the houses. Count how many houses the street has, given only an upper bound `k` on that number, and return the count.

You cannot see the street directly. Your function `houseCount(street, k)` receives a `street` object with these methods, all acting on the house you currently face:

- `street.openDoor()` opens its door;
- `street.closeDoor()` closes its door;
- `street.isDoorOpen()` returns `true` when its door is open, `false` otherwise;
- `street.moveRight()` steps to the next house on the right;
- `street.moveLeft()` steps to the next house on the left.

Because the street is circular, moving right from the last house brings you back to the first one.

Each case is written as `[street, k]`, where `street` lists the doors (`1` open, `0` closed) starting with the house you face and continuing to the right. The judge builds the `street` object from that list; your function never sees the list itself.

validator:
function validate([street, k]) {
  if (!Array.isArray(street) || street.length < 1 || street.length > 1000) return 'street needs 1 to 1000 houses.';
  if (street.some(door => door !== 0 && door !== 1)) return 'Each door is 0 (closed) or 1 (open).';
  if (!Number.isInteger(k) || k > 1000) return 'k is a whole number up to 1000.';
  if (k < street.length) return 'k must be at least the number of houses.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [doors, k] = input;
  const open = doors.map(door => door === 1);
  const n = open.length;
  let position = 0;
  // The door list stays inside this closure; the solution can only use the five methods.
  const street = Object.freeze({
    openDoor() {
      open[position] = true;
    },
    closeDoor() {
      open[position] = false;
    },
    isDoorOpen() {
      return open[position];
    },
    moveRight() {
      position = (position + 1) % n;
    },
    moveLeft() {
      position = (position - 1 + n) % n;
    },
  });
  return solve(street, k);
}

reference:
function houseCount(street, k) {
  for (let step = 0; step < k; step++) {
    street.closeDoor();
    street.moveRight();
  }
  street.openDoor();
  street.moveRight();
  let count = 1;
  while (!street.isDoorOpen()) {
    street.moveRight();
    count++;
  }
  return count;
}

brute:
function houseCount(street, k) {
  // Close every door while walking left, then mark only the house we end up at.
  for (let i = 0; i < k; i++) {
    street.closeDoor();
    street.moveLeft();
  }
  street.openDoor();
  // Try each length c: walk c steps right and look for the mark, then walk back.
  for (let c = 1; c <= k; c++) {
    for (let i = 0; i < c; i++) street.moveRight();
    if (street.isDoorOpen()) return c;
    for (let i = 0; i < c; i++) street.moveLeft();
  }
  return -1;
}

generator:
function generate(rand, size) {
  const k = size === 'large' ? 900 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 10);
  const roll = rand();
  // Sometimes the street is exactly k houses long, sometimes much shorter.
  const n = roll < 0.3 ? k : 1 + Math.floor(rand() * k);
  const bias = rand();
  const street = Array.from({ length: n }, () => (rand() < bias ? 1 : 0));
  return [street, k];
}
